import{_ as a,o as i,c as t,a3 as n}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Waypoint HUD preview","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/waypoints/docs/hud-preview.md"},"headers":[],"relativePath":"packages/waypoints/docs/hud-preview.md","filePath":"packages/waypoints/docs/hud-preview.md","lastUpdated":1791476246000}'),s={name:"packages/waypoints/docs/hud-preview.md"};function o(r,e,l,p,d,c){return i(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="waypoint-hud-preview" tabindex="-1">Waypoint HUD preview <a class="header-anchor" href="#waypoint-hud-preview" aria-label="Permalink to &quot;Waypoint HUD preview&quot;">​</a></h1><p>This build is ready for local preview testing. It is not a published release. The display protocol is pinned to Minecraft Java 26.3 and was tested with Pumpkin <code>0.2.0+26.3-26.51</code>, using plugin API <code>@pumpkinmc/pumpkin-api-ts</code> 0.1.1. Bedrock players can use waypoint commands but receive no HUD.</p><h2 id="build-and-install" tabindex="-1">Build and install <a class="header-anchor" href="#build-and-install" aria-label="Permalink to &quot;Build and install&quot;">​</a></h2><p>From the repository root, with the repository&#39;s pnpm toolchain installed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> turbo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter=@pumpkin-plugins/waypoints</span></span></code></pre></div><p>Copy <code>packages/waypoints/build/waypoints.wasm</code> into the preview server&#39;s <code>plugins/</code> directory, then restart Pumpkin and approve the plugin&#39;s declared permissions at the console. Preserve existing <code>plugins/data/Waypoints/</code> files. Use a full restart when updating this preview: the tested host can reject command permission registration after unloading and loading the plugin again.</p><p>Join with Java 26.3. Vanilla textures supply the built-in icons; no client waypoint mod or resource pack is needed. The test client used mcp-fabric for observation and movement, not waypoint rendering.</p><p>As an operator, stand at a recognizable destination and run:</p><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/wp create &quot;HUD Preview&quot;</span></span>
<span class="line"><span>/wp access public &quot;HUD Preview&quot;</span></span>
<span class="line"><span>/wp set color &quot;HUD Preview&quot; 45C7E8</span></span>
<span class="line"><span>/wp set icon &quot;HUD Preview&quot; minecraft:compass</span></span>
<span class="line"><span>/wp set label &quot;HUD Preview&quot; Preview destination</span></span></code></pre></div><p>New waypoints are restricted by default. The public command makes this demonstration visible to other players; omit it for an operator-only demonstration. <code>/wp delete &quot;HUD Preview&quot;</code> removes it.</p><h2 id="what-informed-the-polish" tabindex="-1">What informed the polish <a class="header-anchor" href="#what-informed-the-polish" aria-label="Permalink to &quot;What informed the polish&quot;">​</a></h2><ul><li><a href="https://github.com/TeamJM/journeymap-docs/blob/6.0.x/docs/en/client/settings/waypoint-beacon.md" target="_blank" rel="noreferrer">JourneyMap&#39;s waypoint settings</a> offer focused labels, small icons, backdrops, and minimum distance controls. This preview uses compact peripheral labels and an arrival fade.</li><li><a href="https://github.com/brainage04/BrainageHUD" target="_blank" rel="noreferrer">BrainageHUD</a> describes consistent apparent size and nearby or focused name visibility. This preview reveals names within 16 blocks or after a settled look, with separate enter/exit thresholds to prevent flicker.</li><li><a href="https://chocolateminecraft.com/update.php?mod_id=0" target="_blank" rel="noreferrer">Xaero&#39;s maintainer changelog</a> describes scaling by view-space depth to avoid enlarged labels in screen corners. The preview applies that principle to display scale while keeping marker positions independent of camera rotation.</li><li><a href="https://www.minecraft.net/en-us/article/minecraft-java-edition-1-19-4" target="_blank" rel="noreferrer">Minecraft&#39;s display entity introduction</a> documents billboards, interpolation, and text appearance. Metadata indices and serializers were checked against the pinned 26.3 registry and client, rather than copied from older protocol examples.</li></ul><p>Client mods render using the current camera on every frame. Pumpkin supplies server position and orientation samples at tick cadence. The preview therefore filters elevation, keeps horizontal bearing responsive, interpolates over one client tick, and projects far markers up to 24 blocks away. Its smooth depth curve avoids the movement-rate kink of the previous fixed eight-block clamp. World anchoring blends in from 16 to three blocks, independently of name visibility. Position jumps larger than eight blocks between samples reset elevation and focus history, preventing stale visual state from drifting into place after a teleport.</p><h2 id="preview-checklist" tabindex="-1">Preview checklist <a class="header-anchor" href="#preview-checklist" aria-label="Permalink to &quot;Preview checklist&quot;">​</a></h2><ol><li>Walk at least 30 blocks away. Look directly at the marker, then away: a far name should reveal after roughly 300 ms and collapse to distance plus icon. Small focus-boundary movements should not flicker. Within 16 blocks, the name should remain visible without focusing it.</li><li>Walk forward, strafe, climb steps, and jump. Expect responsive horizontal bearing and damped ordinary vertical motion. A destination substantially above or below you should still be findable.</li><li>Rotate away and return while stationary. The marker should retain its position and entity identity; it should not fly outward or glide back into view.</li><li>Approach and retreat. Size should remain consistent at a fixed FOV. The marker should blend continuously to its world anchor and stay there within three blocks. Inside two blocks, text, icon, and backdrop should fade together, disappearing at 0.75 blocks.</li><li>Check visibility with a second player, a restricted waypoint, a range limit, and a disabled waypoint. Unauthorized, out-of-range, wrong-dimension, and disabled markers must be absent.</li><li>Inspect names, colors, icons, and long labels against bright sky and dark terrain. HUD truncation must not change stored names or <code>/wp info</code> output.</li><li>Teleport within the dimension to a substantially different height and bearing. Markers should start at the new bearing without carrying elevation or focus state from the previous location.</li></ol><p>Unit coverage checks camera independence, forward movement, vertical damping, transition continuity, apparent size, focus hysteresis, arrival opacity, ACLs, packet encoding, and unavailable Java handles. Real Pumpkin integration tests pass. Live mcp-fabric checks covered name reveal, camera turns, forward movement, world anchoring, arrival fade, teleport history reset, and spyglass behavior without packet decoding failures.</p><h2 id="known-limits-and-remaining-validation" tabindex="-1">Known limits and remaining validation <a class="header-anchor" href="#known-limits-and-remaining-validation" aria-label="Permalink to &quot;Known limits and remaining validation&quot;">​</a></h2><ul><li>Spyglass and modded zoom enlarge labels. Client FOV and reliable Java item-use state are absent from the pinned API; the server cannot perform accurate zoom compensation. Third-person camera offsets and view bobbing are also unavailable.</li><li>Network delay still causes relative motion. The farther projection reduces this error but cannot provide frame-accurate camera attachment. High-latency clients need dedicated preview testing.</li><li>Same-bearing waypoints at different positions can overlap. Only waypoints in the same half-block grid cell receive a deterministic vertical stack.</li><li>Scale, focus, fade, and damping thresholds currently have no user configuration. Broad FOV, resource-pack, multiplayer load, and accessibility testing remain before general release.</li><li>Client mod synchronization, other Java display protocols, Bedrock HUD rendering, and locator bars are outside this preview. The waypoint model remains independent of these presentation choices.</li></ul>`,18)])])}const m=a(s,[["render",o]]);export{u as __pageData,m as default};
